def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Check if opponent defected in the first 79 rounds (indices 0..78)
    early_def = False
    limit = min(n, 79)
    for i in range(limit):
        if history[i][1] == 'D':
            early_def = True
            break

    if not early_def:
        # Opponent has never defected up to round 79
        if n < 79:
            return 'C'
        elif n == 79:
            return 'D'
        elif n == 80:
            return 'C'
        elif n == 81:
            if history[-1][1] == 'D':
                return 'C'
            else:
                return 'D'
        elif n == 82:
            if history[-1][0] == 'C':
                if history[-1][1] == 'C':
                    if n >= 99:
                        return 'D'
                    last_my, last_opp = history[-1]
                    if last_opp == 'D':
                        return 'D'
                    return 'C'
                else:
                    return 'D'
            else:
                return 'D'
        else:  # n >= 83
            if history[82][0] == 'D':
                return 'D'
            else:
                if n >= 99:
                    return 'D'
                last_my, last_opp = history[-1]
                if last_opp == 'D':
                    return 'D'
                return 'C'

    # General TFT with forgiveness
    if n >= 99:
        return 'D'

    opp_d = sum(1 for _, o in history if o == 'D')
    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'D':
            opp_c = n - opp_d
            if opp_c > opp_d * 2 and n > 10:
                return 'C'
            return 'D'
        else:
            return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
